import subprocess, os, sys, pathlib, tempfile, shutil, json, textwrap
BIN=os.path.abspath("/workspace/executable")
def run(args, home="/tmp/home1", env_extra=None, inp=None, cwd=None):
    e=dict(os.environ)
    e["HOME"]=home
    e.pop("CHEAT_CONFIG_PATH",None); e.pop("XDG_CONFIG_HOME",None); e.pop("VISUAL",None); e.pop("EDITOR",None)
    e["TERM"]="dumb"
    if env_extra:
        for k,v in env_extra.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    r=subprocess.run([BIN]+args, capture_output=True, text=True, input=inp, env=e, cwd=cwd)
    return r
def show(args, **kw):
    r=run(args, **kw)
    print(f"$ cheat {' '.join(args)}  exit={r.returncode}")
    print("STDOUT:", repr(r.stdout))
    if r.stderr: print("STDERR:", repr(r.stderr))
    print()
    return r
PY
