package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Minimal YAML subset parser producing go-yaml-like errors for the
// documents cheat consumes (configs and sheet front-matter).

type yamlKind int

const (
	yamlScalar yamlKind = iota
	yamlSeq
	yamlMap
)

type yamlPair struct {
	key string
	keyLine int
	val *yamlNode
}

type yamlNode struct {
	kind   yamlKind
	scalar string // decoded scalar text
	tag    string // str, int, float, bool, null
	line   int
	pairs  []yamlPair
	items  []*yamlNode
}

func (n *yamlNode) tagName() string {
	switch n.kind {
	case yamlSeq:
		return "!!seq"
	case yamlMap:
		return "!!map"
	default:
		switch n.tag {
		case "str":
			return "!!str"
		case "int":
			return "!!int"
		case "float":
			return "!!float"
		case "bool":
			return "!!bool"
		case "null":
			return "!!null"
		}
	}
	return "!!str"
}

type yamlError string

func (e yamlError) Error() string { return string(e) }

type yamlTypeError struct{ lines []string }

func (e *yamlTypeError) Error() string {
	return "yaml: unmarshal errors:\n  " + strings.Join(e.lines, "\n  ")
}

func typeErr(line int, node *yamlNode, target string) string {
	if node.kind == yamlScalar && (node.tag == "str" || node.tag == "int" || node.tag == "float" || node.tag == "bool") {
		// go-yaml quotes scalar values in backquotes for scalar sources.
		return fmt.Sprintf("line %d: cannot unmarshal %s `%s` into %s", line, node.tagName(), node.scalarForError(), target)
	}
	return fmt.Sprintf("line %d: cannot unmarshal %s into %s", line, node.tagName(), target)
}

func (n *yamlNode) scalarForError() string {
	// go-yaml truncates? keep simple.
	return n.scalar
}

// ---------- lexing logical lines ----------
type yamlLine struct {
	raw    string
	indent int
	text   string // content after indent, comment stripped (comments outside quotes/flow handled approximately)
	line   int
}

func stripYAMLComment(s string) string {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' {
				inS = false
			}
			continue
		}
		if inD {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
		case '"':
			inD = true
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				_ = depth
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

func logicalYAMLLines(input string) []yamlLine {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")
	var out []yamlLine
	for idx, raw := range strings.Split(input, "\n") {
		// strip trailing spaces for structural purposes but keep raw
		trimmedRight := strings.TrimRight(raw, " \t")
		indent := 0
		for indent < len(trimmedRight) && trimmedRight[indent] == ' ' {
			indent++
		}
		// tab indentation: count as one (rare)
		text := trimmedRight[indent:]
		text = stripYAMLComment(text)
		if strings.TrimSpace(text) == "" {
			continue
		}
		if text == "---" || text == "..." {
			continue
		}
		out = append(out, yamlLine{raw: raw, indent: indent, text: text, line: idx + 1})
	}
	return out
}

type yamlParser struct {
	lines []yamlLine
	pos   int
}

func parseYAML(input string) (*yamlNode, error) {
	lines := logicalYAMLLines(input)
	if len(lines) == 0 {
		return &yamlNode{kind: yamlScalar, tag: "null", scalar: "", line: 1}, nil
	}
	p := &yamlParser{lines: lines}
	n, err := p.parseNode(lines[0].indent)
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *yamlParser) peek() *yamlLine {
	if p.pos >= len(p.lines) {
		return nil
	}
	return &p.lines[p.pos]
}

func splitKey(text string) (key string, rest string, ok bool) {
	// returns key token and rest after colon (may be "")
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(text); i++ {
		c := text[i]
		if inS {
			if c == '\'' { inS = false }
			continue
		}
		if inD {
			if c == '\\' { i++; continue }
			if c == '"' { inD = false }
			continue
		}
		switch c {
		case '\'': inS = true
		case '"': inD = true
		case '[', '{': depth++
		case ']', '}': depth--
		case ':':
			if depth == 0 && (i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t') {
				return strings.TrimSpace(text[:i]), strings.TrimSpace(text[i+1:]), true
			}
		}
	}
	return "", "", false
}

func decodeYAMLKey(k string, line int) (string, error) {
	if k == "" {
		return "", yamlError("yaml: did not find expected key")
	}
	n, err := parseInlineYAML(k, line)
	if err != nil {
		return "", err
	}
	if n.kind != yamlScalar {
		return "", yamlError("yaml: did not find expected key")
	}
	return n.scalar, nil
}

func (p *yamlParser) parseNode(indent int) (*yamlNode, error) {
	ln := p.peek()
	if ln == nil {
		return &yamlNode{kind: yamlScalar, tag: "null", line: 1}, nil
	}
	if ln.indent < indent {
		return &yamlNode{kind: yamlScalar, tag: "null", line: ln.line}, nil
	}
	ind := ln.indent
	if ln.text == "-" || strings.HasPrefix(ln.text, "- ") {
		return p.parseSequence(ind)
	}
	if _, _, ok := splitKey(ln.text); ok {
		return p.parseMapping(ind, nil)
	}
	// plain scalar on its own line
	p.pos++
	return parseInlineYAML(ln.text, ln.line)
}

type pendingLine struct {
	text string
	line int
	indent int
}

func (p *yamlParser) parseMapping(indent int, first *pendingLine) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMap}
	if first != nil {
		node.line = first.line
	} else if ln := p.peek(); ln != nil {
		node.line = ln.line
	}
	handleLine := func(text string, lineNo int) error {
		keyRaw, rest, ok := splitKey(text)
		if !ok {
			return yamlError("yaml: did not find expected key")
		}
		key, err := decodeYAMLKey(keyRaw, lineNo)
		if err != nil {
			return err
		}
		var val *yamlNode
		if rest != "" {
			if strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
				// block scalar: consume following lines with indent > current key indent
				literal := strings.HasPrefix(rest, "|")
				var parts []string
				for p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
					l := p.lines[p.pos]
					// reconstruct with relative indentation trimmed (approx: strip indent spaces from raw trimmed right)
					raw := strings.TrimRight(l.raw, " \t")
					content := ""
					if len(raw) > l.indent {
						content = raw[l.indent:]
					}
					parts = append(parts, content)
					p.pos++
				}
				sep := "\n"
				if !literal {
					sep = " "
				}
				s := strings.Join(parts, sep)
				if literal && len(parts) > 0 {
					s += "\n"
				}
				val = &yamlNode{kind: yamlScalar, tag: "str", scalar: s, line: lineNo}
			} else {
				v, err := p.parseInlineWithContinuation(rest, lineNo)
				if err != nil {
					return err
				}
				val = v
			}
		} else {
			// look ahead
			nxt := p.peek()
			if nxt == nil {
				val = &yamlNode{kind: yamlScalar, tag: "null", line: lineNo}
			} else if nxt.indent > indent {
				v, err := p.parseNode(nxt.indent)
				if err != nil {
					return err
				}
				val = v
			} else if nxt.indent == indent && (nxt.text == "-" || strings.HasPrefix(nxt.text, "- ")) {
				v, err := p.parseSequence(indent)
				if err != nil {
					return err
				}
				val = v
			} else {
				val = &yamlNode{kind: yamlScalar, tag: "null", line: lineNo}
			}
		}
		node.pairs = append(node.pairs, yamlPair{key: key, keyLine: lineNo, val: val})
		return nil
	}
	if first != nil {
		if err := handleLine(first.text, first.line); err != nil {
			return nil, err
		}
	}
	for {
		ln := p.peek()
		if ln == nil || ln.indent != indent {
			break
		}
		if ln.text == "-" || strings.HasPrefix(ln.text, "- ") {
			break
		}
		if _, _, ok := splitKey(ln.text); !ok {
			break
		}
		p.pos++
		if err := handleLine(ln.text, ln.line); err != nil {
			return nil, err
		}
	}
	return node, nil
}

func (p *yamlParser) parseSequence(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSeq}
	if ln := p.peek(); ln != nil {
		node.line = ln.line
	}
	for {
		ln := p.peek()
		if ln == nil || ln.indent != indent {
			break
		}
		if !(ln.text == "-" || strings.HasPrefix(ln.text, "- ")) {
			break
		}
		lineNo := ln.line
		contentCol := ln.indent + 1
		content := ""
		if ln.text == "-" {
			content = ""
		} else {
			content = strings.TrimPrefix(ln.text, "- ")
			contentCol = ln.indent + 2
			// account for multiple spaces after dash
			restRaw := ln.text[1:]
			trimmed := strings.TrimLeft(restRaw, " ")
			contentCol = ln.indent + 1 + (len(restRaw) - len(trimmed))
			content = trimmed
		}
		p.pos++
		var item *yamlNode
		if content == "" {
			nxt := p.peek()
			if nxt != nil && nxt.indent > indent {
				v, err := p.parseNode(nxt.indent)
				if err != nil {
					return nil, err
				}
				item = v
			} else {
				item = &yamlNode{kind: yamlScalar, tag: "null", line: lineNo}
			}
		} else if _, _, ok := splitKey(content); ok {
			// mapping starting on dash line
			v, err := p.parseMapping(contentCol, &pendingLine{text: content, line: lineNo, indent: contentCol})
			if err != nil {
				return nil, err
			}
			item = v
		} else {
			v, err := p.parseInlineWithContinuation(content, lineNo)
			if err != nil {
				return nil, err
			}
			item = v
		}
		node.items = append(node.items, item)
	}
	return node, nil
}

// parseInlineWithContinuation handles flow collections that span logical lines.
func (p *yamlParser) parseInlineWithContinuation(text string, line int) (*yamlNode, error) {
	combined := text
	// If flow incomplete, keep consuming following logical lines.
	for flowIncomplete(combined) && p.pos < len(p.lines) {
		nxt := p.lines[p.pos]
		p.pos++
		combined += "\n" + nxt.text
	}
	return parseInlineYAML(combined, line)
}

func flowIncomplete(s string) bool {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' { inS = false }
			continue
		}
		if inD {
			if c == '\\' { i++; continue }
			if c == '"' { inD = false }
			continue
		}
		switch c {
		case '\'': inS = true
		case '"': inD = true
		case '[', '{': depth++
		case ']', '}': depth--
		}
	}
	return depth > 0 || inS || inD
}

// ---------- inline parsing ----------
func parseInlineYAML(text string, line int) (*yamlNode, error) {
	text = strings.TrimSpace(text)
	if text == "" {
		return &yamlNode{kind: yamlScalar, tag: "null", scalar: "", line: line}, nil
	}
	switch text[0] {
	case '[':
		seq, consumed, err := parseFlowSeq(text, line)
		if err != nil {
			return nil, err
		}
		_ = consumed
		return seq, nil
	case '{':
		m, _, err := parseFlowMap(text, line)
		if err != nil {
			return nil, err
		}
		return m, nil
	case '\'':
		s, _, err := parseSingleQuoted(text)
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: yamlScalar, tag: "str", scalar: s, line: line}, nil
	case '"':
		s, _, err := parseDoubleQuoted(text)
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: yamlScalar, tag: "str", scalar: s, line: line}, nil
	}
	// block scalar indicator handled elsewhere; if appears here treat as empty
	// plain scalar
	tag := inferPlainTag(text)
	scalar := text
	if tag == "null" {
		scalar = text
	}
	return &yamlNode{kind: yamlScalar, tag: tag, scalar: scalar, line: line}, nil
}

func countNewlines(s string, upTo int) int {
	if upTo > len(s) { upTo = len(s) }
	return strings.Count(s[:upTo], "\n")
}

func parseFlowSeq(text string, baseLine int) (*yamlNode, int, error) {
	node := &yamlNode{kind: yamlSeq, line: baseLine}
	i := 1 // skip [
	skipWS := func() {
		for i < len(text) && (text[i] == ' ' || text[i] == '\t' || text[i] == '\n' || text[i] == '\r') { i++ }
	}
	skipWS()
	if i < len(text) && text[i] == ']' {
		return node, i + 1, nil
	}
	for {
		skipWS()
		if i >= len(text) {
			return nil, 0, yamlError(fmt.Sprintf("yaml: line %d: did not find expected node content", baseLine + countNewlines(text, i)))
		}
		if text[i] == ']' {
			return node, i + 1, nil
		}
		// find end of this element at top level (comma or ])
		start := i
		// parse element via recursive flow or scalar token
		var item *yamlNode
		var err error
		switch text[i] {
		case '[':
			sub, cons, e := parseFlowSeq(text[i:], baseLine + countNewlines(text, i))
			if e != nil { return nil, 0, e }
			item = sub; i += cons
		case '{':
			sub, cons, e := parseFlowMap(text[i:], baseLine + countNewlines(text, i))
			if e != nil { return nil, 0, e }
			item = sub; i += cons
		case '\'':
			s, cons, e := parseSingleQuoted(text[i:])
			if e != nil { return nil, 0, e }
			item = &yamlNode{kind: yamlScalar, tag: "str", scalar: s, line: baseLine + countNewlines(text, start)}
			i += cons
		case '"':
			s, cons, e := parseDoubleQuoted(text[i:])
			if e != nil { return nil, 0, e }
			item = &yamlNode{kind: yamlScalar, tag: "str", scalar: s, line: baseLine + countNewlines(text, start)}
			i += cons
		default:
			j := i
			depth := 0
			inS, inD := false, false
			for j < len(text) {
				c := text[j]
				if inS { if c == '\'' { inS = false }; j++; continue }
				if inD { if c == '\\' { j += 2; continue }; if c == '"' { inD = false }; j++; continue }
				switch c {
				case '\'': inS = true
				case '"': inD = true
				case '[', '{': depth++
				case ']', '}':
					if depth == 0 { goto doneScalar }
					depth--
				case ',':
					if depth == 0 { goto doneScalar }
				}
				j++
			}
		doneScalar:
			scalText := strings.TrimSpace(text[i:j])
			tag := inferPlainTag(scalText)
			item = &yamlNode{kind: yamlScalar, tag: tag, scalar: scalText, line: baseLine + countNewlines(text, start)}
			i = j
			err = nil
		}
		_ = err
		node.items = append(node.items, item)
		skipWS()
		if i >= len(text) {
			return nil, 0, yamlError(fmt.Sprintf("yaml: line %d: did not find expected ',' or ']'", baseLine + countNewlines(text, i)))
		}
		if text[i] == ',' {
			i++
			skipWS()
			if i < len(text) && text[i] == ']' {
				return node, i + 1, nil
			}
			continue
		}
		if text[i] == ']' {
			return node, i + 1, nil
		}
		return nil, 0, yamlError(fmt.Sprintf("yaml: line %d: did not find expected ',' or ']'", baseLine + countNewlines(text, i)))
	}
}

func parseFlowMap(text string, baseLine int) (*yamlNode, int, error) {
	node := &yamlNode{kind: yamlMap, line: baseLine}
	i := 1
	skipWS := func() { for i < len(text) && (text[i]==' '||text[i]=='\t'||text[i]=='\n'||text[i]=='\r') { i++ } }
	skipWS()
	if i < len(text) && text[i] == '}' {
		return node, i + 1, nil
	}
	for {
		skipWS()
		if i >= len(text) { return nil, 0, yamlError(fmt.Sprintf("yaml: line %d: did not find expected node content", baseLine)) }
		// parse key up to :
		// simplest: find colon depth 0
		start := i
		depth := 0
		for i < len(text) {
			c := text[i]
			if c == '[' || c == '{' { depth++ }
			if c == ']' || c == '}' { if depth==0 { break }; depth-- }
			if c == ':' && depth == 0 { break }
			if c == ',' && depth == 0 { break }
			i++
		}
		keyText := strings.TrimSpace(text[start:i])
		var val *yamlNode
		if i < len(text) && text[i] == ':' {
			i++
			// value up to , or }
			skipWS()
			valStart := i
			if i < len(text) && (text[i]=='[' || text[i]=='{' || text[i]=='\'' || text[i]=='"') {
				var cons int
				var e error
				var sub *yamlNode
				switch text[i] {
				case '[': sub, cons, e = parseFlowSeq(text[i:], baseLine+countNewlines(text,i))
				case '{': sub, cons, e = parseFlowMap(text[i:], baseLine+countNewlines(text,i))
				case '\'':
					var s string; s, cons, e = parseSingleQuoted(text[i:]); if e==nil { sub=&yamlNode{kind:yamlScalar,tag:"str",scalar:s,line:baseLine} }
				case '"':
					var s string; s, cons, e = parseDoubleQuoted(text[i:]); if e==nil { sub=&yamlNode{kind:yamlScalar,tag:"str",scalar:s,line:baseLine} }
				}
				if e != nil { return nil, 0, e }
				val = sub; i += cons
			} else {
				j := i; d2:=0
				for j < len(text) {
					c:=text[j]
					if c=='['||c=='{' {d2++}
					if c==']'||c=='}' { if d2==0 {break}; d2-- }
					if c==',' && d2==0 {break}
					j++
				}
				sText := strings.TrimSpace(text[valStart:j])
				val = &yamlNode{kind: yamlScalar, tag: inferPlainTag(sText), scalar: sText, line: baseLine}
				i = j
			}
		} else {
			val = &yamlNode{kind: yamlScalar, tag: "null", line: baseLine}
		}
		keyNode, _ := parseInlineYAML(keyText, baseLine)
		key := ""
		if keyNode != nil && keyNode.kind == yamlScalar { key = keyNode.scalar }
		node.pairs = append(node.pairs, yamlPair{key: key, keyLine: baseLine, val: val})
		skipWS()
		if i < len(text) && text[i] == ',' { i++; continue }
		if i < len(text) && text[i] == '}' { return node, i + 1, nil }
		if i >= len(text) { return nil, 0, yamlError(fmt.Sprintf("yaml: line %d: did not find expected ',' or '}'", baseLine)) }
	}
}

func parseSingleQuoted(s string) (string, int, error) {
	// s starts with '
	var b strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if c == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				b.WriteByte('\'')
				i += 2
				continue
			}
			return b.String(), i + 1, nil
		}
		b.WriteByte(c)
		i++
	}
	return "", 0, yamlError("yaml: found unexpected end of stream")
}

func parseDoubleQuoted(s string) (string, int, error) {
	var b strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if c == '"' {
			return b.String(), i + 1, nil
		}
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case 'n': b.WriteByte('\n'); i += 2
			case 't': b.WriteByte('\t'); i += 2
			case 'r': b.WriteByte('\r'); i += 2
			case '0': b.WriteByte(0); i += 2
			case 'a': b.WriteByte('\a'); i += 2
			case 'b': b.WriteByte('\b'); i += 2
			case 'f': b.WriteByte('\f'); i += 2
			case 'v': b.WriteByte('\v'); i += 2
			case '\\': b.WriteByte('\\'); i += 2
			case '"': b.WriteByte('"'); i += 2
			case '/': b.WriteByte('/'); i += 2
			case 'x', 'u', 'U':
				nb := 2
				if n == 'u' { nb = 4 }
				if n == 'U' { nb = 8 }
				if i+2+nb <= len(s) {
					if v, err := strconv.ParseInt(s[i+2:i+2+nb], 16, 32); err == nil {
						b.WriteRune(rune(v))
						i += 2 + nb
						continue
					}
				}
				i += 2
			case '\n':
				i += 2
			default:
				b.WriteByte(n); i += 2
			}
			continue
		}
		b.WriteByte(c)
		i++
	}
	return "", 0, yamlError("yaml: found unexpected end of stream")
}

func inferPlainTag(s string) string {
	if s == "" || s == "~" || s == "null" || s == "Null" || s == "NULL" {
		return "null"
	}
	if s == "true" || s == "True" || s == "TRUE" || s == "false" || s == "False" || s == "FALSE" {
		return "bool"
	}
	if isYAMLInt(s) {
		return "int"
	}
	if isYAMLFloat(s) {
		return "float"
	}
	return "str"
}

func isYAMLInt(s string) bool {
	if s == "" { return false }
	t := s
	if t[0] == '+' || t[0] == '-' { t = t[1:] }
	if t == "" { return false }
	if strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X") {
		for _, c := range t[2:] {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') || c == '_') { return false }
		}
		return len(t) > 2
	}
	if strings.HasPrefix(t, "0o") || strings.HasPrefix(t, "0O") {
		for _, c := range t[2:] { if c < '0' || c > '7' { return false } }
		return len(t) > 2
	}
	for _, c := range t {
		if (c < '0' || c > '9') && c != '_' { return false }
	}
	return true
}

func isYAMLFloat(s string) bool {
	if s == ".inf" || s == ".Inf" || s == ".INF" || s == "-.inf" || s == "+.inf" || s == ".nan" || s == ".NaN" || s == ".NAN" {
		return true
	}
	// simple float pattern
	if !strings.ContainsAny(s, ".eE") { return false }
	_, err := strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
	return err == nil
}

// ---- decoding helpers ----

func nodeToString(n *yamlNode, errs *[]string) string {
	if n == nil { return "" }
	if n.kind != yamlScalar {
		*errs = append(*errs, typeErr(n.line, n, "string"))
		return ""
	}
	if n.tag == "null" {
		return ""
	}
	return n.scalar
}

func nodeToBool(n *yamlNode, errs *[]string) bool {
	if n == nil { return false }
	if n.kind != yamlScalar || n.tag != "bool" {
		if n.kind == yamlScalar && n.tag == "null" {
			// null into bool? go-yaml leaves false
			return false
		}
		*errs = append(*errs, typeErr(n.line, n, "bool"))
		return false
	}
	return n.scalar == "true" || n.scalar == "True" || n.scalar == "TRUE"
}

func nodeToStringSlice(n *yamlNode, errs *[]string) []string {
	if n == nil { return nil }
	if n.kind == yamlScalar && n.tag == "null" {
		return nil
	}
	if n.kind != yamlSeq {
		*errs = append(*errs, typeErr(n.line, n, "[]string"))
		return nil
	}
	out := []string{}
	for _, it := range n.items {
		if it.kind != yamlScalar {
			*errs = append(*errs, typeErr(it.line, it, "string"))
			continue
		}
		if it.tag == "null" {
			out = append(out, "")
		} else {
			out = append(out, it.scalar)
		}
	}
	return out
}

func mapLookup(n *yamlNode, key string) *yamlNode {
	if n == nil || n.kind != yamlMap {
		return nil
	}
	for _, pr := range n.pairs {
		if pr.key == key {
			return pr.val
		}
	}
	return nil
}
