	Path      string
	Cheatpath cheatpath
	CheatpathIndex int
	Text      string
	Syntax    string
	Tags      []string // combined, sorted
}

func normalizeLineEndings(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	return s
}

type frontmatter struct {
	Syntax string
	Tags   []string
}

func parseFrontmatter(raw string) (frontmatter, string, error) {
	var fm frontmatter
	fm.Tags = []string{}
	lineEnding := "\n"
	if strings.Contains(raw, "\r\n") {
		lineEnding = "\r\n"
	}
	delim := "---" + lineEnding
	if !strings.HasPrefix(raw, delim) {
		return fm, normalizeLineEndings(raw), nil
	}
	rest := raw[len(delim):]
	idx := strings.Index(rest, delim)
	if idx < 0 {
		return fm, "", fmt.Errorf("failed to parse front-matter: failed to delimit frontmatter")
	}
	fmText := rest[:idx]
	body := rest[idx+len(delim):]
	root, err := parseYAML(fmText)
	if err != nil {
		return fm, "", fmt.Errorf("failed to parse front-matter: failed to unmarshal frontmatter: %w", err)
	}
	if root.kind == yamlMap {
		var errs []string
		for _, pr := range root.pairs {
			switch pr.key {
			case "syntax":
				fm.Syntax = nodeToString(pr.val, &errs)
			case "tags":
				fm.Tags = nodeToStringSlice(pr.val, &errs)
			}
		}
		if len(errs) > 0 {
			return fm, "", fmt.Errorf("failed to parse front-matter: failed to unmarshal frontmatter: %w", &yamlTypeError{lines: errs})
		}
	} else if root.kind == yamlScalar && root.tag == "null" {
		// empty frontmatter
	} else {
		// frontmatter that is not a map: go-yaml would error into struct
		var errs []string
		errs = append(errs, typeErr(root.line, root, "struct { Syntax string \"yaml:\\\"syntax\\\"\"; Tags []string \"yaml:\\\"tags\\\"\" }"))
		// Simpler fallback: mimic cannot unmarshal into frontmatter struct name as observed? Use generic.
		// Actually original messages we've seen are for fields; for non-map it's rare.
		return fm, "", fmt.Errorf("failed to parse front-matter: failed to unmarshal frontmatter: %w", &yamlTypeError{lines: errs})
	}
	if fm.Tags == nil {
		fm.Tags = []string{}
	}
	return fm, normalizeLineEndings(body), nil
}

func loadSheet(title, path string, cp cheatpath, idx int) (sheet, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return sheet{}, fmt.Errorf("failed to read file: %s, %w", path, err)
	}
	fm, text, err := parseFrontmatter(string(data))
	if err != nil {
		return sheet{}, err
	}
	tags := []string{}
	tags = append(tags, cp.Tags...)
	tags = append(tags, fm.Tags...)
	sort.Strings(tags)
	return sheet{
		Title:          title,
		Path:           path,
		Cheatpath:      cp,
		CheatpathIndex: idx,
		Text:           text,
		Syntax:         fm.Syntax,
		Tags:           tags,
	}, nil
}

func loadSheets(cfg *config) ([]sheet, error) {
	var all []sheet
	for idx, cp := range cfg.Cheatpaths {
		sheets, err := loadSheetsFromPath(cp, idx)
		if err != nil {
			return nil, fmt.Errorf("failed to list cheatsheets: %w", err)
		}
		all = append(all, sheets...)
	}
	if all == nil {
		all = []sheet{}
	}
	return all, nil
}

func loadSheetsFromPath(cp cheatpath, idx int) ([]sheet, error) {
	var sheets []sheet
	var loadErr error
	walkErr := filepath.Walk(cp.Path, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}
		if strings.Contains(info.Name(), ".") {
			return nil
		}
		rel, rerr := filepath.Rel(cp.Path, path)
		if rerr != nil {
			rel = path
		}
		title := rel
		// Trim extension-like suffix as original does for "." root case
		if ext := filepath.Ext(title); ext != "" && title == "." {
			title = strings.TrimSuffix(title, ext)
		}
		// filepath.Rel uses OS separator; titles use forward slashes (on linux same)
		title = filepath.ToSlash(title)
		s, err := loadSheet(title, path, cp, idx)
		if err != nil {
			loadErr = fmt.Errorf("failed to load sheet: %s, path: %s, err: %w", title, path, err)
			return loadErr
		}
		sheets = append(sheets, s)
		return nil
	})
	if loadErr != nil {
		return nil, fmt.Errorf("failed to load cheatsheets: %w", loadErr)
	}
	if walkErr != nil {
		return nil, fmt.Errorf("failed to load cheatsheets: failed to walk path: %w", walkErr)
	}
	return sheets, nil
}

