{"command":"cat > flags.go <<'GO'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type options struct {
	All        bool
	Brief      bool
	Colorize   bool
	Completion string
	Conf       bool
	Directories bool
	Edit       string
	Help       bool
	Init       bool
	List       bool
	Path       string
	Regex      bool
	Rm         string
	Search     string
	Tag        string
	Tags       bool
	Update     bool
	Version    bool
	changed    map[string]bool
	args       []string
}

type flagDef struct {
	Long  string
	Short string // one char or ""
	Kind  string // "bool" or "string"
	Usage string // raw usage (with backticks)
}

var flagDefs = []flagDef{
	{Long: "all", Short: "a", Kind: "bool", Usage: "Search among all cheatpaths"},
	{Long: "brief", Short: "b", Kind: "bool", Usage: "List cheatsheets without file paths"},
	{Long: "colorize", Short: "c", Kind: "bool", Usage: "Colorize output"},
	{Long: "completion", Short: "", Kind: "string", Usage: "Generate shell completion script (`shell`: bash, zsh, fish, powershell)"},
	{Long: "conf", Short: "", Kind: "bool", Usage: "Display the config file path"},
	{Long: "directories", Short: "d", Kind: "bool", Usage: "List cheatsheet directories"},
	{Long: "edit", Short: "e", Kind: "string", Usage: "Edit `cheatsheet`"},
	{Long: "help", Short: "h", Kind: "bool", Usage: "help for cheat"},
	{Long: "init", Short: "", Kind: "bool", Usage: "Write a default config file to stdout"},
	{Long: "list", Short: "l", Kind: "bool", Usage: "List cheatsheets"},
	{Long: "path", Short: "p", Kind: "string", Usage: "Return only sheets found on cheatpath `name`"},
	{Long: "regex", Short: "r", Kind: "bool", Usage: "Treat search <phrase> as a regex"},
	{Long: "rm", Short: "", Kind: "string", Usage: "Remove (delete) `cheatsheet`"},
	{Long: "search", Short: "s", Kind: "string", Usage: "Search cheatsheets for `phrase`"},
	{Long: "tag", Short: "t", Kind: "string", Usage: "Return only sheets matching `tag`"},
	{Long: "tags", Short: "T", Kind: "bool", Usage: "List all tags in use"},
	{Long: "update", Short: "u", Kind: "bool", Usage: "Update git-backed cheatpaths"},
	{Long: "version", Short: "v", Kind: "bool", Usage: "Print the version number"},
}

func findLong(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].Long == name {
			return &flagDefs[i]
		}
	}
	return nil
}
func findShort(c byte) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].Short == string(c) {
			return &flagDefs[i]
		}
	}
	return nil
}

func (o *options) setBool(def *flagDef, val bool) {
	o.changed[def.Long] = true
	switch def.Long {
	case "all": o.All = val
	case "brief": o.Brief = val
	case "colorize": o.Colorize = val
	case "conf": o.Conf = val
	case "directories": o.Directories = val
	case "help": o.Help = val
	case "init": o.Init = val
	case "list": o.List = val
	case "regex": o.Regex = val
	case "tags": o.Tags = val
	case "update": o.Update = val
	case "version": o.Version = val
	}
}
func (o *options) setString(def *flagDef, val string) {
	o.changed[def.Long] = true
	switch def.Long {
	case "completion": o.Completion = val
	case "edit": o.Edit = val
	case "path": o.Path = val
	case "rm": o.Rm = val
	case "search": o.Search = val
	case "tag": o.Tag = val
	}
}

func flagDisplayName(def *flagDef) string {
	if def.Short != "" {
		return fmt.Sprintf("-%s, --%s", def.Short, def.Long)
	}
	return fmt.Sprintf("--%s", def.Long)
}

func parseBoolValue(def *flagDef, val string) (bool, error) {
	b, err := strconv.ParseBool(val)
	if err != nil {
		return false, fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", val, flagDisplayName(def), val)
	}
	return b, nil
}

func parseFlags(args []string) (*options, error) {
	o := &options{changed: map[string]bool{}}
	afterDashDash := false
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if afterDashDash {
			o.args = append(o.args, arg)
			continue
		}
		if arg == "--" {
			afterDashDash = true
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' && arg[1] == '-' {
			// long flag
			body := arg[2:]
			if body == "" || body[0] == '-' || body[0] == '=' {
				return nil, fmt.Errorf("bad flag syntax: %s", arg)
			}
			name := body
			val := ""
			hasVal := false
			if idx := strings.Index(body, "="); idx >= 0 {
				name = body[:idx]
				val = body[idx+1:]
				hasVal = true
			}
			def := findLong(name)
			if def == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if def.Kind == "bool" {
				if hasVal {
					b, err := parseBoolValue(def, val)
					if err != nil { return nil, err }
					o.setBool(def, b)
				} else {
					o.setBool(def, true)
				}
			} else {
				if hasVal {
					o.setString(def, val)
				} else {
					if i >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					o.setString(def, args[i])
					i++
				}
			}
			continue
		}
		if len(arg) >= 1 && arg[0] == '-' && arg != "-" {
			// short cluster
			shorthands := arg[1:]
			for len(shorthands) > 0 {
				c := shorthands[0]
				def := findShort(c)
				if def == nil {
					return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", rune(c), shorthands)
				}
				if def.Kind == "bool" {
					// if remainder is =value (len(cluster)>2)
					if len(shorthands) > 2 && shorthands[1] == '=' {
						val := shorthands[2:]
						b, err := parseBoolValue(def, val)
						if err != nil { return nil, err }
						o.setBool(def, b)
						shorthands = ""
						break
					}
					o.setBool(def, true)
					shorthands = shorthands[1:]
					continue
				} else {
					// string
					rest := shorthands[1:]
