						val := shorthands[2:]
						b, err := parseBoolValue(def, val)
						if err != nil { return nil, err }
						o.setBool(def, b)
						shorthands = ""
						break
					}
					o.setBool(def, true)
					shorthands = shorthands[1:]
					continue
				} else {
					// string
					rest := shorthands[1:]
					if len(rest) > 0 {
						var val string
						if rest[0] == '=' && len(rest) > 1 {
							val = rest[1:]
						} else {
							val = rest
						}
						o.setString(def, val)
						shorthands = ""
						break
					}
					if i >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: %q in -%s", rune(c), shorthands)
					}
					o.setString(def, args[i])
					i++
					shorthands = ""
					break
				}
			}
			continue
		}
		o.args = append(o.args, arg)
	}
	return o, nil
}
