package main

import (
	"fmt"
	"math"
	"strings"
)

// Token types (simplified to classes)
const (
	tokText = iota
	tokComment
	tokKeyword
	tokOperator
	tokNumber
	tokString
	tokName        // language dependent colour handled by style mapping nameFG
	tokNameFunc
	tokError
)

type token struct {
	typ int
	val string
}

type styleEntry struct {
	fg     string // hex rrggbb or "" for none
	bg     string
	bold   bool
	italic bool
	// for 256 special overrides
	fg256 *int
	bg256 *int
}

type langKind int

const (
	langBash langKind = iota
	langPython
	langJS // javascript/typescript/go-like (names green)
	langGo
	langPlain
	langGeneric // python-like names white
)

func lexerForSyntax(syntax string, text string) langKind {
	s := strings.ToLower(strings.TrimSpace(syntax))
	if s == "" {
		return langBash
	}
	switch s {
	case "bash", "sh", "shell", "zsh", "ksh", "dash", "fish":
		return langBash
	case "python", "py", "python3", "cython", "py3":
		return langPython
	case "javascript", "js", "jsx", "tsx":
		return langJS
	case "typescript", "ts":
		return langJS
	case "go", "golang":
		return langGo
	case "plaintext", "text", "plain", "none":
		return langPlain
	case "markdown", "md":
		return langPlain
	}
	// unknown syntax: content-based fallback (chroma analyse approximation)
	if hasBashShebang(text) {
		return langBash
	}
	// echo/comment heuristic which matches the observed analyse outcome for
	// shell-like snippets
	if looksShellLike(text) {
		return langBashLikeAnalysed()
	}
	return langPlain
}

func hasBashShebang(text string) bool {
	if !strings.HasPrefix(text, "#!") {
		return false
	}
	first := text
	if idx := strings.Index(text, "\n"); idx >= 0 {
		first = text[:idx]
	}
	return strings.Contains(first, "sh") || strings.Contains(first, "bash") || strings.Contains(first, "zsh")
}

func looksShellLike(text string) bool {
	// If text contains # comment or shell-ish first words, chroma analysis
	// frequently selects a shell/python-ish lexer. We approximate by bash
	// but with python-like word splitting: we implement that through
	// langGeneric when invoked below (handled in lexerForSyntax caller
	// by returning generic via a sentinel?).
	// To keep pipeline simple, we signal via langGeneric.
	return strings.Contains(text, "#") || strings.Contains(text, "echo ")
}

func langBashLikeAnalysed() langKind { return langGeneric }

var bashKeywords = map[string]bool{
	"if": true, "then": true, "else": true, "elif": true, "fi": true, "case": true, "esac": true, "for": true, "while": true, "until": true, "do": true, "done": true, "in": true, "function": true, "select": true, "time": true, "return": true, "break": true, "continue": true, "shift": true, "export": true, "local": true, "declare": true, "readonly": true, "set": true, "unset": true, "source": true, "eval": true, "exec": true, "test": true, "true": true, "false": true, "exit": true,
}
var pythonKeywords = map[string]bool{
	"def": true, "class": true, "return": true, "if": true, "elif": true, "else": true, "for": true, "while": true, "try": true, "except": true, "finally": true, "with": true, "as": true, "import": true, "from": true, "pass": true, "break": true, "continue": true, "lambda": true, "yield": true, "global": true, "nonlocal": true, "assert": true, "del": true, "raise": true, "in": true, "is": true, "and": true, "or": true, "not": true, "None": true, "True": true, "False": true, "async": true, "await": true,
}
var jsKeywords = map[string]bool{
	"const": true, "let": true, "var": true, "function": true, "return": true, "if": true, "else": true, "for": true, "while": true, "do": true, "switch": true, "case": true, "default": true, "break": true, "continue": true, "new": true, "class": true, "extends": true, "import": true, "from": true, "export": true, "try": true, "catch": true, "finally": true, "throw": true, "typeof": true, "instanceof": true, "in": true, "of": true, "void": true, "delete": true, "yield": true, "async": true, "await": true, "this": true, "null": true, "undefined": true, "true": true, "false": true, "static": true, "get": true, "set": true,
}
var goKeywords = map[string]bool{
	"package": true, "import": true, "func": true, "var": true, "const": true, "type": true, "struct": true, "interface": true, "map": true, "chan": true, "go": true, "defer": true, "return": true, "if": true, "else": true, "for": true, "range": true, "switch": true, "case": true, "default": true, "break": true, "continue": true, "select": true, "fallthrough": true, "goto": true,
}

func isWordChar(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c >= 0x80
}
func isWordStart(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c >= 0x80
}

// tokenize whole text; tokens may contain newlines (strings etc). Formatter splits.
func tokenize(text string, lang langKind) []token {
	if lang == langPlain {
		// chroma plaintext: one token per line content
		if text == "" {
			return nil
		}
		var toks []token
		// Split keeping newlines attached to line token? Our formatter handles
		// tokens without newline separately; we return lines as tokens and rely
		// on format to insert newlines.
		lines := strings.SplitAfter(text, "\n")
		for _, ln := range lines {
			if ln == "" { continue }
			trimmed := strings.TrimSuffix(ln, "\n")
			toks = append(toks, token{tokText, trimmed})
			if strings.HasSuffix(ln, "\n") {
				toks = append(toks, token{tokText, "\n"})
			}
		}
		return toks
	}
