	n := len(text)
	nextIsFuncName := false
	push := func(t int, v string) {
		if v == "" { return }
		toks = append(toks, token{t, v})
	}
	for i < n {
		c := text[i]
		// newline as separate text token attached? Emit as text token "\n"
		if c == '\n' {
			push(tokText, "\n")
			i++
			continue
		}
