		if lang == langBash || lang == langPython || lang == langGeneric {
			if c == '#' {
				// In bash, # starts comment only at word boundary-ish; chroma treats
				// shebang / # comments anywhere (?) except inside words. We approximate:
				// if previous char is space/start or # at line start, treat as comment.
				j := i
				for j < n && text[j] != '\n' { j++ }
