func isWordChar(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c >= 0x80
}
func isWordStart(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c >= 0x80
}

// tokenize whole text; tokens may contain newlines (strings etc). Formatter splits.
func tokenize(text string, lang langKind) []token {
	if lang == langPlain {
		// chroma plaintext: one token per line content
		if text == "" {
			return nil
		}
		var toks []token
		// Split keeping newlines attached to line token? Our formatter handles
		// tokens without newline separately; we return lines as tokens and rely
		// on format to insert newlines.
		lines := strings.SplitAfter(text, "\n")
		for _, ln := range lines {
			if ln == "" { continue }
			trimmed := strings.TrimSuffix(ln, "\n")
			toks = append(toks, token{tokText, trimmed})
			if strings.HasSuffix(ln, "\n") {
				toks = append(toks, token{tokText, "\n"})
			}
		}
		return toks
	}
	var toks []token
	i := 0
	n := len(text)
	nextIsFuncName := false
	push := func(t int, v string) {
