		}
		// operators / punctuation single char grouping for some
		if strings.ContainsRune("=+-*/%<>!&|^~?:@$;,.()[]{}", rune(c)) {
			// In Go, = and punctuation are Text, not operator pink except some ops.
			if lang == langGo && strings.ContainsRune("=()[]{};,.", rune(c)) {
				push(tokText, string(c))
			} else if lang == langPython && strings.ContainsRune("()[]{}:;,.", rune(c)) {
				push(tokText, string(c))
			} else if lang == langJS && strings.ContainsRune("()[]{};,.", rune(c)) {
				// JS: () {} ; etc often Text, = + are operator pink? observed () was text, = pink, + pink, => text in JS (231) vs TS pink.
				push(tokText, string(c))
			} else if lang == langBash && strings.ContainsRune("()[]{};", rune(c)) {
				// bash parentheses pink in observed? () was pink (197)
				push(tokOperator, string(c))
			} else {
				push(tokOperator, string(c))
			}
			i++
			// reset func name flag on non-space token except? simplified
			if c != ' ' {
				// keep nextIsFuncName only over whitespace; punctuation clears
				if !(c == ' ') { nextIsFuncName = nextIsFuncName && false }
			}
			continue
		}
		// Error characters for Go/JS lexers: e.g. # in Go/JS
		if (lang == langJS || lang == langGo) && c == '#' {
			push(tokError, string(c))
			i++
			continue
		}
		// any other char
		push(tokText, text[i:i+1])
		i++
	}
	return toks
}

// ---- styles ----

func styleFor(name string, tokTyp int, lang langKind) styleEntry {
	// returns entry; zero fg (empty) means no colour (may still have italic)
	switch name {
	case "":
		// chroma styles.Get("") behaviour observed: comment italic, others plain
		if tokTyp == tokComment {
			return styleEntry{italic: true}
		}
		return styleEntry{}
	case "monokai":
		switch tokTyp {
		case tokComment: return styleEntry{fg: "75715e"}
		case tokKeyword: return styleEntry{fg: "66d9ef"}
		case tokOperator: return styleEntry{fg: "f92672"}
		case tokNumber: return styleEntry{fg: "ae81ff"}
		case tokString: return styleEntry{fg: "e6db74"}
		case tokNameFunc: return styleEntry{fg: "a6e22e"}
		case tokError: fg89 := 89; bg232 := 232; return styleEntry{fg: "f92672", bg: "272822", fg256: &fg89, bg256: &bg232}
		default: return styleEntry{fg: "f8f8f2"}
		}
	case "github":
		switch tokTyp {
		case tokComment: return styleEntry{fg: "57606a"}
		case tokKeyword: return styleEntry{fg: "cf222e"}
		case tokOperator: return styleEntry{fg: "0550ae"}
		case tokNumber: return styleEntry{fg: "0550ae"}
		case tokString: return styleEntry{fg: "0a3069"}
		case tokNameFunc: return styleEntry{fg: "1f2328"}
		case tokError: return styleEntry{fg: "cf222e"}
		default: return styleEntry{fg: "1f2328"}
		}
	case "dracula":
		switch tokTyp {
		case tokComment: return styleEntry{fg: "6272a4"}
		case tokKeyword: return styleEntry{fg: "ff79c6"}
		case tokOperator: return styleEntry{fg: "ff79c6"}
		case tokNumber: return styleEntry{fg: "bd93f9"}
		case tokString: return styleEntry{fg: "f1fa8c"}
		case tokNameFunc: return styleEntry{fg: "50fa7b"}
		default: return styleEntry{fg: "f8f8f2"}
		}
	default:
		// fallback / swapoff style used by chroma for unknown styles
		switch tokTyp {
		case tokComment: return styleEntry{fg: "00ffff"} // approx 256 -> 6
		case tokKeyword: return styleEntry{fg: "00ffff"}
		case tokOperator: return styleEntry{fg: "00ffff"}
		case tokNumber: return styleEntry{fg: "ff00ff"}
		case tokString: return styleEntry{fg: "ffff00"}
		case tokNameFunc: return styleEntry{fg: "00ff00"}
		default:
			// swapoff text ~ e4e4e4 -> 254
			fg := 254; return styleEntry{fg: "e4e4e4", fg256: &fg}
		}
	}
}

func hexToRGB(hex string) (int, int, int) {
	if len(hex) == 3 {
		hex = string([]byte{hex[0], hex[0], hex[1], hex[1], hex[2], hex[2]})
	}
	var v int
	fmt.Sscanf(hex, "%x", &v)
	return (v >> 16) & 255, (v >> 8) & 255, v & 255
}

func rgbTo256(r, g, b int) int {
	// approximate xterm 256 conversion like chroma
	if r == g && g == b {
		if r < 8 { return 16 }
		if r > 248 { return 231 }
		return int(math.Round(float64(r-8)/247*24)) + 232
	}
	to6 := func(c int) int {
		if c < 48 { return 0 }
		if c < 115 { return 1 }
		return int(math.Round(float64(c-55)/40.0))
		// note chroma uses a colour distance palette; this approximates
	}
	// Use chroma-like nearest cube/grey selection via palette distance
	best := 16
	bestDist := math.MaxFloat64
	// build xterm palette
	type rgb struct{ r, g, b int }
	var pal []rgb
	base := []rgb{{0,0,0},{128,0,0},{0,128,0},{128,128,0},{0,0,128},{128,0,128},{0,128,128},{192,192,192},{128,128,128},{255,0,0},{0,255,0},{255,255,0},{0,0,255},{255,0,255},{0,255,255},{255,255,255}}
	pal = append(pal, base...)
	levels := []int{0, 95, 135, 175, 215, 255}
	for _, rr := range levels {
		for _, gg := range levels {
			for _, bb := range levels {
				pal = append(pal, rgb{rr, gg, bb})
			}
		}
	}
	for i := 0; i < 24; i++ {
		v := 8 + i*10
		pal = append(pal, rgb{v, v, v})
	}
	_ = to6
	for idx, c := range pal {
		d := math.Sqrt(float64((r-c.r)*(r-c.r) + (g-c.g)*(g-c.g) + (b-c.b)*(b-c.b)))
		if d < bestDist {
			bestDist = d
			best = idx
		}
	}
	return best
}

func rgbToANSI16(r, g, b int) (int, bool) {
	type rgb struct{ r, g, b int }
	pal := []rgb{{0,0,0},{128,0,0},{0,128,0},{128,128,0},{0,0,128},{128,0,128},{0,128,128},{192,192,192},{128,128,128},{255,0,0},{0,255,0},{255,255,0},{0,0,255},{255,0,255},{0,255,255},{255,255,255}}
	best := 0
	bestDist := math.MaxFloat64
	for idx, c := range pal {
		d := float64((r-c.r)*(r-c.r) + (g-c.g)*(g-c.g) + (b-c.b)*(b-c.b))
		if d < bestDist { bestDist = d; best = idx }
	}
	code := 30 + (best % 8)
	bright := best >= 8
	return code, bright
}

func formatColored(text string, syntax string, cfg *config) string {
	if text == "" {
		return ""
	}
	lang := lexerForSyntax(syntax, text)
	toks := tokenize(text, lang)
	formatter := cfg.Formatter
	styleName := cfg.Style
	var sb strings.Builder
	writeToken := func(tok token) {
		if tok.val == "" {
			// mirrors occasional empty-token output when token is "\n" handled outside
			return
		}
		// split by newline: newline written outside styles
		parts := strings.Split(tok.val, "\n")
		for pi, part := range parts {
			if pi > 0 {
				sb.WriteString("\n")
			}
			if part == "" {
				// If token was exactly "\n", original formatter emits an empty
				// styled text token for some lexers. We approximate: a pure
				// newline token becomes newline only (no empty sequence) except
				// when caller inserts it specially.
				if tok.val == "\n" && pi == 0 {
					// newline already handled by caller logic below
				}
				continue
			}
			entry := styleFor(styleName, tok.typ, lang)
			seq := escapeSequence(entry, formatter)
			if seq == "" {
				sb.WriteString(part)
			} else {
				sb.WriteString(seq)
				sb.WriteString(part)
				sb.WriteString("\x1b[0m")
			}
		}
		// trailing newline of token: Split already inserted newlines between parts,
		// but if token ends with newline and part last empty we need newline.
		if strings.HasSuffix(tok.val, "\n") {
			// The loop wrote newlines between, and final empty skipped; ensure trailing
			// newline count is preserved:
			// Count trailing newlines:
			// Simpler: split logic above lost final newline. Add it if not already.
			// Our tokens: newline tokens are separate (tokText "\n") except strings etc.
			// For those, add newline now.
			if tok.typ == tokString || tok.typ == tokComment {
				sb.WriteString("\n")
			}
		}
	}
	for _, tok := range toks {
		if tok.val == "\n" {
			sb.WriteString("\n")
			continue
		}
		writeToken(tok)
	}
	return sb.String()
}

func escapeSequence(e styleEntry, formatter string) string {
	if e.fg == "" && e.bg == "" && !e.bold && !e.italic {
		return ""
	}
	switch formatter {
	case "terminal":
		var parts []string
		bright := false
		code := 0
		if e.fg != "" {
			r, g, b := hexToRGB(e.fg)
			code, bright = rgbToANSI16(r, g, b)
		}
		if bright || e.bold {
			parts = append(parts, "\x1b[1m")
		}
		if e.italic {
			parts = append(parts, "\x1b[3m")
		}
		if e.fg != "" {
			parts = append(parts, fmt.Sprintf("\x1b[%dm", code))
		}
		return strings.Join(parts, "")
	case "terminal16m":
		var sb strings.Builder
		if e.bold { sb.WriteString("\x1b[1m") }
		if e.italic { sb.WriteString("\x1b[3m") }
		// chroma terminal16m merges? Observed only fg sequence for monokai (no bold separate)
		// For entries with colours, return single 38;2 sequence (plus separate if attrs)
		var main strings.Builder
		if e.bold || e.italic {
			main.WriteString(sb.String())
		}
		if e.fg != "" {
			r, g, b := hexToRGB(e.fg)
			main.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b))
		}
		if e.bg != "" {
			r, g, b := hexToRGB(e.bg)
			main.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm", r, g, b))
		}
		return main.String()
	default: // terminal256 and "" fallback to terminal? Original: formatter "" + monokai gave terminal (16 colors)
		if formatter == "" {
			// chroma formatters.Get("") returns terminal fallback
			return escapeSequence(e, "terminal")
		}
		var sb strings.Builder
		if e.bold { sb.WriteString("\x1b[1m") }
		if e.italic { sb.WriteString("\x1b[3m") }
		if e.fg != "" {
			fg256 := 0
			if e.fg256 != nil {
				fg256 = *e.fg256
			} else {
				r, g, b := hexToRGB(e.fg)
				fg256 = rgbTo256(r, g, b)
			}
			sb.WriteString(fmt.Sprintf("\x1b[38;5;%dm", fg256))
		}
		if e.bg != "" {
			bg256 := 0
			if e.bg256 != nil {
				bg256 = *e.bg256
			} else {
				r, g, b := hexToRGB(e.bg)
				bg256 = rgbTo256(r, g, b)
			}
			sb.WriteString(fmt.Sprintf("\x1b[48;5;%dm", bg256))
		}
		return sb.String()
	}
}
GO"}

{"command":"cat > completion.go <<'GO'
package main

import (
	_ "embed"
	"fmt"
	"sort"
	"strings"
)

//go:embed assets/completions/bash.txt
var completionBash string

//go:embed assets/completions/zsh.txt
var completionZsh string

//go:embed assets/completions/fish.txt
var completionFish string

//go:embed assets/completions/powershell.txt
var completionPowershell string

func completionScript(shell string) string {
	switch shell {
	case "bash":
		return completionBash
	case "zsh":
		return completionZsh
	case "fish":
		return completionFish
	case "powershell":
		return completionPowershell
	}
	return ""
}

type completionData struct {
	Sheets []string
	Tags   []string
	Paths  []string
}

func getCompletionData() completionData {
	data := completionData{Sheets: []string{}, Tags: []string{}, Paths: []string{}}
	candidates, err := configCandidates()
	if err != nil {
		return data
	}
	cfgPath, ok := findExistingConfig(candidates)
	if !ok {
		return data
	}
	cfg, err := loadConfigFromFile(cfgPath)
	if err != nil {
		return data
	}
	// silence warnings on reload? loadConfigFromFile would have printed warnings
	// for nonexistent paths during original load too; in __complete original
	// appears to swallow errors. We have already loaded; paths come from cfg.
	for _, cp := range cfg.Cheatpaths {
		data.Paths = append(data.Paths, cp.Name)
	}
	sheets, err := loadSheets(cfg)
	if err != nil {
		// still paths available, sheets empty
		return data
	}
	seenSheet := map[string]bool{}
	tagSet := map[string]bool{}
	for _, s := range sheets {
		if !seenSheet[s.Title] {
			seenSheet[s.Title] = true
			data.Sheets = append(data.Sheets, s.Title)
		}
		for _, t := range s.Tags {
			tagSet[t] = true
		}
	}
	sort.Strings(data.Sheets)
	for t := range tagSet {
		data.Tags = append(data.Tags, t)
	}
	sort.Strings(data.Tags)
	return data
}

func directiveName(code int) string {
	if code == 4 {
		return "ShellCompDirectiveNoFileComp"
	}
	return "ShellCompDirectiveDefault"
}

// handles __complete / __completeNoDesc; returns exit code
func runCompletionCommand(noDesc bool, args []string) int {
	if len(args) == 0 {
		fmt.Fprintf(stderrOut, "requires at least 1 arg(s), only received 0\n")
		return 1
	}
	toComplete := args[len(args)-1]
	preceding := args[:len(args)-1]

	// If preceding contains "--", everything after it is positional
	// Determine final args parsing loosely for error reporting
	// Cobra first checks if toComplete looks like a flag value with =
	if idx := strings.Index(toComplete, "="); idx > 0 && strings.HasPrefix(toComplete, "-") {
		flagNamePart := toComplete[:idx]
		// resolve flag def
		var def *flagDef
		if strings.HasPrefix(flagNamePart, "--") {
			def = findLong(strings.TrimPrefix(flagNamePart, "--"))
		} else if len(flagNamePart) == 2 && flagNamePart[0] == '-' {
			def = findShort(flagNamePart[1])
		}
		if def != nil && def.Kind == "string" {
			switch def.Long {
			case "tag", "path", "edit", "rm":
				data := getCompletionData()
				var vals []string
				switch def.Long {
				case "tag": vals = data.Tags
				case "path": vals = data.Paths
				default: vals = data.Sheets
				}
				for _, v := range vals {
					fmt.Fprintln(stdoutOut, v)
				}
				fmt.Fprintln(stdoutOut, ":4")
				fmt.Fprintf(stderrOut, "Completion ended with directive: %s\n", directiveName(4))
				return 0
			default:
				fmt.Fprintln(stdoutOut, ":0")
				fmt.Fprintf(stderrOut, "Completion ended with directive: %s\n", directiveName(0))
				return 0
			}
		}
		if def != nil && def.Kind == "bool" {
			fmt.Fprintln(stdoutOut, ":0")
			fmt.Fprintf(stderrOut, "Completion ended with directive: %s\n", directiveName(0))
			return 0
		}
	}

	// Detect parse errors of preceding args
	// Use our flag parser on preceding; if error, cobra reports debug
	if _, err := parseFlagsForCompletion(preceding); err != nil {
		fmt.Fprintln(stdoutOut, ":0")
		// format args as cobra prints: [%s] joined by space
		fmt.Fprintf(stderrOut, "[Debug] [Error] Error while parsing flags from args [%s]: %s\n", strings.Join(preceding, " "), err.Error())
		fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveDefault\n")
		return 0
	}

	// After "--", positional completion
	hasDashDash := false
	for _, a := range preceding {
		if a == "--" {
			hasDashDash = true
			break
		}
	}
	// If a preceding argument is a string flag awaiting value:
	// Cobra handles case where last preceding token is a flag requiring value
	if !hasDashDash && len(preceding) > 0 {
		last := preceding[len(preceding)-1]
		var def *flagDef
		if strings.HasPrefix(last, "--") && !strings.Contains(last, "=") {
			def = findLong(last[2:])
		} else if len(last) == 2 && last[0] == '-' {
			def = findShort(last[1])
		} else if len(last) > 1 && last[0] == '-' && last[1] != '-' {
			// cluster ending with string flag: e.g. -lt with no separate value
			// The cluster's last char might be a string flag awaiting next arg
			c := last[len(last)-1]
			d := findShort(c)
			if d != nil && d.Kind == "string" {
				def = d
			}
		}
		if def != nil && def.Kind == "string" {
			data := getCompletionData()
			var vals []string
			code := 4
			switch def.Long {
			case "tag": vals = data.Tags
			case "path": vals = data.Paths
			case "edit", "rm": vals = data.Sheets
			default:
				code = 0
				vals = nil
			}
			for _, v := range vals {
				fmt.Fprintln(stdoutOut, v)
			}
			fmt.Fprintf(stdoutOut, ":%d\n", code)
			fmt.Fprintf(stderrOut, "Completion ended with directive: %s\n", directiveName(code))
			return 0
		}
	}

	// Flag name completion if toComplete begins with -
	if !hasDashDash && strings.HasPrefix(toComplete, "-") && toComplete != "-" || (!hasDashDash && toComplete == "-") {
		// parsed preceding flags changed set
		parsed, _ := parseFlagsForCompletion(preceding)
		changed := map[string]bool{}
		if parsed != nil {
			changed = parsed.changed
		}
		if strings.HasPrefix(toComplete, "--") {
			prefix := toComplete[2:]
			for _, def := range flagDefs {
				if changed[def.Long] && def.Long != "help" {
					// Cobra omits already-used flags for long completion
					// (observed --tag/-l). Keep help.
				}
				if changed[def.Long] {
					continue
				}
				if !strings.HasPrefix(def.Long, prefix) {
					continue
				}
				if noDesc {
					fmt.Fprintf(stdoutOut, "--%s\n", def.Long)
				} else {
					fmt.Fprintf(stdoutOut, "--%s\t%s\n", def.Long, def.Usage)
				}
			}
			fmt.Fprintln(stdoutOut, ":4")
			fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
			return 0
		}
		if strings.HasPrefix(toComplete, "-") {
			prefix := toComplete[1:]
			// If prefix is exactly one char matching a flag, cobra returns that shorthand
			// Our generic generation: iterate flags in long order; emit long then short
			// Filter by name prefix for long, and by short char for short.
			// For toComplete == "-" emit all.
			// For longer prefix like "-t", only -t matches.
			singleCharMatch := false
			if len(prefix) == 1 {
				if d := findShort(prefix[0]); d != nil {
					singleCharMatch = true
					if noDesc {
						fmt.Fprintf(stdoutOut, "-%s\n", d.Short)
					} else {
						fmt.Fprintf(stdoutOut, "-%s\t%s\n", d.Short, d.Usage)
					}
					fmt.Fprintln(stdoutOut, ":4")
					fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
					return 0
				}
			}
			if !singleCharMatch {
				// if prefix does not match any short first char, emit none
				// (cobra filters flags whose name/short matches prefix)
				if len(prefix) >= 1 {
					// Check if any long flag starts with prefix? But with single dash
					// cobra still only matches shorthand first char; unknown -> none
					// e.g. -x -> none
					fmt.Fprintln(stdoutOut, ":4")
					fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
					return 0
				}
			}
			for _, def := range flagDefs {
				if changed[def.Long] {
					// For short-form completion, cobra included a string flag
					// already used in one observed case; we approximate by
					// including flags except bool flags already used.
					if def.Kind == "bool" {
						continue
					}
				}
				if noDesc {
					fmt.Fprintf(stdoutOut, "--%s\n", def.Long)
					if def.Short != "" {
						fmt.Fprintf(stdoutOut, "-%s\n", def.Short)
					}
				} else {
					fmt.Fprintf(stdoutOut, "--%s\t%s\n", def.Long, def.Usage)
					if def.Short != "" {
						fmt.Fprintf(stdoutOut, "-%s\t%s\n", def.Short, def.Usage)
					}
				}
			}
			fmt.Fprintln(stdoutOut, ":4")
			fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
			return 0
		}
	}

	// positional completion
	// If there's already a positional arg in preceding (excluding flags/values)
	positionals := extractPositionals(preceding)
	if len(positionals) > 0 {
		fmt.Fprintln(stdoutOut, ":4")
		fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
		return 0
	}
	data := getCompletionData()
	for _, v := range data.Sheets {
		fmt.Fprintln(stdoutOut, v)
	}
	fmt.Fprintln(stdoutOut, ":4")
	fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
	return 0
}

func parseFlagsForCompletion(args []string) (*options, error) {
	// Use same parser but cobra completion tolerates last incomplete flags;
	// our parser will error for flags needing arg at end of preceding:
	// In cobra completion, preceding args ending with a flag expecting a value
	// is not a parse error (the toComplete IS the value). parseFlags would
	// consume toComplete conceptually, but preceding list alone would fail if
	// last is a string flag. So relax: if final arg is a string flag, pretend ok.
	if len(args) > 0 {
		last := args[len(args)-1]
		if strings.HasPrefix(last, "--") && !strings.Contains(last, "=") {
			if d := findLong(last[2:]); d != nil && d.Kind == "string" {
				// parse without it
				return parseFlags(args[:len(args)-1])
			}
		}
		if len(last) >= 2 && last[0] == '-' && last[1] != '-' {
			// last char string flag cluster
			c := last[len(last)-1]
			if d := findShort(c); d != nil && d.Kind == "string" {
				// If the cluster itself is exactly that flag, drop it
				if len(last) == 2 {
					return parseFlags(args[:len(args)-1])
				}
				// else parse cluster minus string part? Simplify: parse without last arg
				// but add changed for earlier bool flags in cluster? ignoring.
				return parseFlags(args[:len(args)-1])
			}
		}
	}
	return parseFlags(args)
}

func extractPositionals(args []string) []string {
	parsed, err := parseFlagsForCompletion(args)
	if err != nil {
		return nil
	}
	return parsed.args
}
GO"}

