		var def *flagDef
		if strings.HasPrefix(flagNamePart, "--") {
			def = findLong(strings.TrimPrefix(flagNamePart, "--"))
		} else if len(flagNamePart) == 2 && flagNamePart[0] == '-' {
			def = findShort(flagNamePart[1])
		}
		if def != nil && def.Kind == "string" {
			switch def.Long {
			case "tag", "path", "edit", "rm":
				data := getCompletionData()
				var vals []string
				switch def.Long {
				case "tag": vals = data.Tags
				case "path": vals = data.Paths
