				fmt.Fprintln(stdoutOut, v)
			}
			fmt.Fprintf(stdoutOut, ":%d\n", code)
			fmt.Fprintf(stderrOut, "Completion ended with directive: %s\n", directiveName(code))
			return 0
		}
	}

