			prefix := toComplete[2:]
			for _, def := range flagDefs {
				if changed[def.Long] && def.Long != "help" {
					// Cobra omits already-used flags for long completion
					// (observed --tag/-l). Keep help.
				}
				if changed[def.Long] {
					continue
				}
				if !strings.HasPrefix(def.Long, prefix) {
					continue
				}
				if noDesc {
					fmt.Fprintf(stdoutOut, "--%s\n", def.Long)
				} else {
					fmt.Fprintf(stdoutOut, "--%s\t%s\n", def.Long, def.Usage)
				}
			}
			fmt.Fprintln(stdoutOut, ":4")
			fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
			return 0
		}
		if strings.HasPrefix(toComplete, "-") {
			prefix := toComplete[1:]
			// If prefix is exactly one char matching a flag, cobra returns that shorthand
			// Our generic generation: iterate flags in long order; emit long then short
			// Filter by name prefix for long, and by short char for short.
			// For toComplete == "-" emit all.
			// For longer prefix like "-t", only -t matches.
			singleCharMatch := false
			if len(prefix) == 1 {
				if d := findShort(prefix[0]); d != nil {
					singleCharMatch = true
					if noDesc {
						fmt.Fprintf(stdoutOut, "-%s\n", d.Short)
					} else {
						fmt.Fprintf(stdoutOut, "-%s\t%s\n", d.Short, d.Usage)
					}
					fmt.Fprintln(stdoutOut, ":4")
					fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
					return 0
				}
			}
			if !singleCharMatch {
				// if prefix does not match any short first char, emit none
				// (cobra filters flags whose name/short matches prefix)
				if len(prefix) >= 1 {
					// Check if any long flag starts with prefix? But with single dash
					// cobra still only matches shorthand first char; unknown -> none
					// e.g. -x -> none
					fmt.Fprintln(stdoutOut, ":4")
					fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
					return 0
				}
			}
