				if changed[def.Long] {
					// For short-form completion, cobra included a string flag
					// already used in one observed case; we approximate by
					// including flags except bool flags already used.
					if def.Kind == "bool" {
						continue
					}
				}
				if noDesc {
					fmt.Fprintf(stdoutOut, "--%s\n", def.Long)
					if def.Short != "" {
						fmt.Fprintf(stdoutOut, "-%s\n", def.Short)
					}
				} else {
					fmt.Fprintf(stdoutOut, "--%s\t%s\n", def.Long, def.Usage)
					if def.Short != "" {
						fmt.Fprintf(stdoutOut, "-%s\t%s\n", def.Short, def.Usage)
