	// If there's already a positional arg in preceding (excluding flags/values)
	positionals := extractPositionals(preceding)
	if len(positionals) > 0 {
		fmt.Fprintln(stdoutOut, ":4")
		fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
		return 0
	}
	data := getCompletionData()
	for _, v := range data.Sheets {
		fmt.Fprintln(stdoutOut, v)
	}
	fmt.Fprintln(stdoutOut, ":4")
	fmt.Fprintf(stderrOut, "Completion ended with directive: ShellCompDirectiveNoFileComp\n")
	return 0
}

func parseFlagsForCompletion(args []string) (*options, error) {
	// Use same parser but cobra completion tolerates last incomplete flags;
	// our parser will error for flags needing arg at end of preceding:
	// In cobra completion, preceding args ending with a flag expecting a value
	// is not a parse error (the toComplete IS the value). parseFlags would
	// consume toComplete conceptually, but preceding list alone would fail if
	// last is a string flag. So relax: if final arg is a string flag, pretend ok.
	if len(args) > 0 {
		last := args[len(args)-1]
		if strings.HasPrefix(last, "--") && !strings.Contains(last, "=") {
			if d := findLong(last[2:]); d != nil && d.Kind == "string" {
				// parse without it
				return parseFlags(args[:len(args)-1])
			}
		}
		if len(last) >= 2 && last[0] == '-' && last[1] != '-' {
			// last char string flag cluster
			c := last[len(last)-1]
			if d := findShort(c); d != nil && d.Kind == "string" {
				// If the cluster itself is exactly that flag, drop it
				if len(last) == 2 {
					return parseFlags(args[:len(args)-1])
				}
				// else parse cluster minus string part? Simplify: parse without last arg
				// but add changed for earlier bool flags in cluster? ignoring.
				return parseFlags(args[:len(args)-1])
			}
		}
	}
	return parseFlags(args)
}

func extractPositionals(args []string) []string {
	parsed, err := parseFlagsForCompletion(args)
	if err != nil {
		return nil
	}
	return parsed.args
}
