	}
	// If remote is ancestor of local, already up to date
	if _, _, err := runGit(cp.Path, "merge-base", "--is-ancestor", remoteRef, "HEAD"); err == nil {
		return fmt.Sprintf("%s: ok", cp.Name), "", false
	}
	return "", fmt.Sprintf("%s: error (non-fast-forward update)", cp.Name), true
}

func cmdUpdate(cfg *config, opts *options) int {
