{"command":"cat > main.go <<'GO'
package main

import (
	"bufio"
	_ "embed"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"text/tabwriter"
)

//go:embed assets/help.txt
var helpText string

var stdoutOut = os.Stdout
var stderrOut = os.Stderr

var stdinReader *bufio.Reader

func getStdinReader() *bufio.Reader {
	if stdinReader == nil {
		stdinReader = bufio.NewReader(os.Stdin)
	}
	return stdinReader
}

func main() {
	os.Exit(runMain(os.Args[1:]))
}

func runMain(argv []string) int {
	// Hidden cobra completion command
	if len(argv) > 0 && (argv[0] == "__complete" || argv[0] == "__completeNoDesc") {
		return runCompletionCommand(argv[0] == "__completeNoDesc", argv[1:])
	}
	opts, err := parseFlags(argv)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	if opts.Help {
		fmt.Fprint(stdoutOut, helpText)
		return 0
	}
	if len(opts.args) > 1 {
		fmt.Fprintf(stderrOut, "accepts at most %d arg(s), received %d\n", 1, len(opts.args))
		return 1
	}
	if opts.Init {
		if code, err := cmdInit(); err != nil {
			fmt.Fprintln(stderrOut, err.Error())
			return code
		} else {
			return code
		}
	}
	if opts.Version {
		fmt.Fprintln(stdoutOut, "5.1.0")
		return 0
	}
	if opts.changed["completion"] {
		switch opts.Completion {
		case "bash", "zsh", "fish", "powershell":
			fmt.Fprint(stdoutOut, completionScript(opts.Completion))
			return 0
		default:
			fmt.Fprintf(stderrOut, "unsupported shell: %s (valid: bash, zsh, fish, powershell)\n", opts.Completion)
			return 1
		}
	}
	// Config resolution / loading
	candidates, err := configCandidates()
	if err != nil {
		fmt.Fprintf(stderrOut, "failed to load config: %s\n", err.Error())
		return 1
	}
	cfgPath, found := findExistingConfig(candidates)
	if !found {
		// installer flow
		code := handleMissingConfig(candidates)
		return code
	}
	cfg, err := loadConfigFromFile(cfgPath)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	// validate --path option
	if opts.changed["path"] {
		exists := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.Path {
				exists = true
				break
			}
		}
		if !exists {
			fmt.Fprintf(stderrOut, "invalid option --path: cheatpath does not exist: %s\n", opts.Path)
			return 1
		}
	}
	return dispatch(cfg, opts)
}

func cmdInit() (int, error) {
	candidates, err := configCandidates()
	if err != nil {
		return 1, fmt.Errorf("failed to read config paths: %w", err)
	}
	candidate := ""
	if len(candidates) > 0 {
		candidate = candidates[0]
	}
	fmt.Fprint(stdoutOut, renderInitTemplate(candidate))
	return 0, nil
}

// handleMissingConfig returns exit code (does not proceed to command)
func handleMissingConfig(candidates []string) int {
	// first prompt
	fmt.Fprint(stdoutOut, "A config file was not found. Would you like to create one now? [Y/n]: ")
	answer, err := promptYesNo()
	if err != nil {
		fmt.Fprintf(stderrOut, "failed to create config: failed to prompt: %s\n", err.Error())
		return 1
	}
	if !answer {
		return 0
	}
	// installer
	candidate := ""
	if len(candidates) > 0 {
		candidate = candidates[0]
	}
	if err := runInstaller(candidate); err != nil {
		fmt.Fprintf(stderrOut, "failed to run installer: %s\n", err.Error())
		return 1
	}
	return 0
}

func promptYesNo() (bool, error) {
	answer, err := readPromptLine()
	if err != nil {
		return false, err
	}
	a := strings.ToLower(strings.TrimSpace(answer))
	return a == "" || a == "y", nil
}

// promptYesNoWrapped returns error already wrapped as "failed to prompt: ..."
func promptYesNoWrapped() (bool, error) {
	answer, err := readPromptLine()
	if err != nil {
		return false, fmt.Errorf("failed to prompt: %w", err)
	}
	a := strings.ToLower(strings.TrimSpace(answer))
	return a == "" || a == "y", nil
}

func readPromptLine() (string, error) {
	r := getStdinReader()
	line, err := r.ReadString('\n')
	if err != nil {
		if len(line) > 0 {
			return line, nil
		}
		// io.EOF prints as "EOF"
		return "", err
	}
	return line, nil
}

func runInstaller(candidate string) error {
	fmt.Fprint(stdoutOut, "Would you like to download the community cheatsheets? [Y/n]: ")
	yes, err := promptYesNoWrapped()
	if err != nil {
		// err already is "failed to prompt: EOF"; installer layer wraps again
		return fmt.Errorf("failed to prompt: %w", err)
	}
	cheatsheetsDir := cheatSheetsDirForCandidate(candidate)
	if yes {
		communityDir := filepath.Join(cheatsheetsDir, "community")
		fmt.Fprintf(stdoutOut, "Cloning community cheatsheets to %s.\n", communityDir)
		if err := cloneCommunity(cheatsheetsDir, communityDir); err != nil {
			return err // cloneCommunity already wraps as failed to clone...
		}
	}
	// create directories personal, work
	for _, name := range []string{"personal", "work"} {
		dir := filepath.Join(cheatsheetsDir, name)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fmt.Errorf("failed to create directory: %w", err)
		}
	}
	// write config file
	content := renderInitTemplate(candidate)
	content = strings.TrimSuffix(content, "\n")
	if err := createConfigFile(candidate, content); err != nil {
		return err
	}
	fmt.Fprintf(stdoutOut, "Created config file: %s\n", candidate)
	fmt.Fprintln(stdoutOut, "Please read this file for advanced configuration information.")
	return nil
}

func createConfigFile(path string, content string) error {
	if err := writeFileSimple(path, content); err != nil {
		return fmt.Errorf("failed to create config file: %w", err)
	}
	return nil
}

func writeFileSimple(path string, content string) error {
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	return nil
}

func cloneCommunity(cheatsheetsDir, communityDir string) error {
	// mirror side-effect: cheatsheets dir exists after failed clone
	_ = os.MkdirAll(cheatsheetsDir, 0755)
	// Attempt HTTP discovery like go-git; produce Go http error string on failure
	url := "https://github.com/cheat/cheatsheets.git/info/refs?service=git-upload-pack"
	resp, err := http.Get(url)
	if err != nil {
		return fmt.Errorf("failed to clone cheatsheets: failed to clone cheatsheets: %w", err)
	}
	resp.Body.Close()
	if resp.StatusCode != 200 {
		return fmt.Errorf("failed to clone cheatsheets: failed to clone cheatsheets: unexpected status: %s", resp.Status)
	}
	// If network reachable, use git clone to actually fetch
	if _, err := os.Stat(communityDir); err == nil {
		// remove empty existing dir
		_ = os.Remove(communityDir)
	}
	cmd := exec.Command("git", "clone", "--quiet", "https://github.com/cheat/cheatsheets.git", communityDir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		msg := strings.TrimSpace(string(out))
		if msg == "" {
			msg = err.Error()
		}
		return fmt.Errorf("failed to clone cheatsheets: failed to clone cheatsheets: %s", msg)
	}
	return nil
}

// ---------- pager ----------

func writeViaPager(cfg *config, output string) error {
	if cfg.Pager == "" {
		_, err := fmt.Fprint(stdoutOut, output)
		return err
	}
	parts := strings.Fields(cfg.Pager)
	if len(parts) == 0 {
		_, err := fmt.Fprint(stdoutOut, output)
		return err
	}
	cmd := exec.Command(parts[0], parts[1:]...)
	cmd.Stdin = strings.NewReader(output)
	cmd.Stdout = stdoutOut
	cmd.Stderr = stderrOut
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to write to pager: %w", err)
	}
	return nil
}

func pagerOut(cfg *config, output string) int {
	if err := writeViaPager(cfg, output); err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	return 0
}

// ---------- dispatch ----------

func dispatch(cfg *config, opts *options) int {
	if opts.Conf {
		fmt.Fprintln(stdoutOut, cfg.Path)
		return 0
	}
	if opts.Directories {
		cps := filterCheatpathsByPath(cfg.Cheatpaths, opts)
		var buf strings.Builder
		w := tabwriter.NewWriter(&buf, 0, 0, 1, ' ', 0)
		for _, cp := range cps {
			fmt.Fprintf(w, "%s:\t%s\n", cp.Name, cp.Path)
		}
		w.Flush()
		return pagerOut(cfg, buf.String())
	}
	if opts.changed["edit"] {
		return cmdEdit(cfg, opts)
	}
	if opts.List || opts.Brief {
		return cmdList(cfg, opts, opts.Brief)
	}
	if opts.Tags {
		sheets, err := loadSheets(cfg)
		if err != nil {
			fmt.Fprintln(stderrOut, err.Error())
			return 1
		}
		sheets = filterByPath(sheets, opts)
		tagSet := map[string]bool{}
		for _, s := range sheets {
			for _, t := range s.Tags {
				tagSet[t] = true
			}
		}
		var tags []string
		for t := range tagSet {
			tags = append(tags, t)
		}
		sort.Strings(tags)
		var buf strings.Builder
		for _, t := range tags {
			buf.WriteString(t + "\n")
		}
		return pagerOut(cfg, buf.String())
	}
	if opts.Update {
		return cmdUpdate(cfg, opts)
	}
	if opts.changed["search"] {
		return cmdSearch(cfg, opts)
	}
	if opts.changed["rm"] {
		return cmdRemove(cfg, opts)
	}
	if len(opts.args) > 0 {
		name := opts.args[0]
		if opts.All {
			return cmdShowAll(cfg, opts, name)
		}
		return cmdShow(cfg, opts, name)
	}
	if opts.Tag != "" {
		// list with tag filter
		return cmdList(cfg, opts, false)
	}
	fmt.Fprint(stdoutOut, helpText)
	return 0
}

func isColorize(cfg *config, opts *options) bool {
	if opts.Colorize {
		return true
	}
	if cfg.Colorize && isTerminal(stdoutOut) {
		return true
	}
	return false
}

func isTerminal(f *os.File) bool {
	info, err := f.Stat()
	if err != nil {
		return false
	}
	return (info.Mode() & os.ModeCharDevice) != 0
}

func colourizeText(cfg *config, opts *options, text string, syntax string) string {
	if !isColorize(cfg, opts) {
		return text
	}
	return formatColored(text, syntax, cfg)
}

// display of a single sheet
func cmdShow(cfg *config, opts *options, name string) int {
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	cands := filterExactTitle(filtered, name)
	s, ok := pickMostLocal(cands)
	if !ok {
		fmt.Fprintf(stdoutOut, "No cheatsheet found for '%s'.\n", name)
		return 2
	}
	out := colourizeText(cfg, opts, s.Text, s.Syntax)
	return pagerOut(cfg, out)
}

func formatSheetBlock(cfg *config, opts *options, s sheet, body string) string {
	// body is already (filtered) raw text
	trimmed := strings.TrimSpace(body)
	var content string
	if isColorize(cfg, opts) {
		colored := formatColored(trimmed, s.Syntax, cfg)
		content = "\t" + strings.ReplaceAll(colored, "\n", "\n\t")
		// title line
		return fmt.Sprintf("%s \x1b[2m(%s)\x1b[0m\n%s", s.Title, s.Cheatpath.Name, content)
	}
	content = "\t" + strings.ReplaceAll(trimmed, "\n", "\n\t")
	return fmt.Sprintf("%s (%s)\n%s", s.Title, s.Cheatpath.Name, content)
}

func cmdShowAll(cfg *config, opts *options, name string) int {
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	cands := filterExactTitle(filtered, name)
	sortForSearch(cands)
	var blocks []string
	for _, s := range cands {
		b := formatSheetBlock(cfg, opts, s, s.Text)
		blocks = append(blocks, b+"\n")
	}
	out := strings.Join(blocks, "\n")
	return pagerOut(cfg, out)
}

func cmdList(cfg *config, opts *options, brief bool) int {
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	if len(opts.args) > 0 {
		term := strings.ToLower(opts.args[0])
		var f []sheet
		for _, s := range filtered {
			if strings.Contains(strings.ToLower(s.Title), term) {
				f = append(f, s)
			}
		}
		filtered = f
	}
	sortByTitle(filtered)
	if len(filtered) == 0 {
		return 2
	}
	var buf strings.Builder
	w := tabwriter.NewWriter(&buf, 0, 0, 1, ' ', 0)
	if brief {
		fmt.Fprintln(w, "title:\ttags:")
		for _, s := range filtered {
			fmt.Fprintf(w, "%s\t%s\n", s.Title, strings.Join(s.Tags, ","))
		}
	} else {
		fmt.Fprintln(w, "title:\tfile:\ttags:")
		for _, s := range filtered {
			fmt.Fprintf(w, "%s\t%s\t%s\n", s.Title, s.Path, strings.Join(s.Tags, ","))
		}
	}
	w.Flush()
	return pagerOut(cfg, buf.String())
}

var paragraphsRe = regexp.MustCompile(`\n\n+`)

func cmdSearch(cfg *config, opts *options) int {
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	if len(opts.args) > 0 {
		filtered = filterExactTitle(filtered, opts.args[0])
	}
	pattern := opts.Search
	if !opts.Regex {
		pattern = "(?i)" + pattern
	}
	re, err := regexp.Compile(pattern)
	if err != nil {
		fmt.Fprintf(stderrOut, "failed to compile regexp: %s, %s\n", pattern, err.Error())
		return 1
	}
	sortForSearch(filtered)
	var blocks []string
	for _, s := range filtered {
		// split into paragraphs: runs of 2+ newlines as separator
		// First trim? Original splits sheet text; we split untrimmed and trim chunks.
		chunks := paragraphsRe.Split(s.Text, -1)
		var matching []string
		for _, ch := range chunks {
			t := strings.TrimSpace(ch)
			// matching is tested on the chunk (trimmed equivalent)
			if re.MatchString(t) {
				matching = append(matching, t)
			}
		}
		if len(matching) == 0 {
			continue
		}
		joined := strings.Join(matching, "\n\n")
		b := formatSheetBlock(cfg, opts, s, joined)
		blocks = append(blocks, b)
	}
	out := strings.Join(blocks, "\n\n")
	return pagerOut(cfg, out)
}

func cmdRemove(cfg *config, opts *options) int {
	name := opts.Rm
	if err := validateCheatsheetName(name); err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	cands := filterExactTitle(filtered, name)
	s, ok := pickMostLocal(cands)
	if !ok {
		fmt.Fprintf(stderrOut, "No cheatsheet found for '%s'.\n", name)
		return 2
	}
	if s.Cheatpath.ReadOnly {
		fmt.Fprintf(stderrOut, "cheatsheet '%s' is read-only.\n", name)
		return 1
	}
	if err := os.Remove(s.Path); err != nil {
		fmt.Fprintf(stderrOut, "failed to delete sheet: %s, %s\n", s.Title, err.Error())
		return 1
	}
	return 0
}

func cmdEdit(cfg *config, opts *options) int {
	name := opts.Edit
	if err := validateCheatsheetName(name); err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	cands := filterExactTitle(filtered, name)
	var editPath string
	if s, ok := pickMostLocal(cands); ok {
		if !s.Cheatpath.ReadOnly {
			editPath = s.Path
		} else {
			// copy to most local writeable (path-filtered cheatpaths)
			destCP, ok := mostLocalWriteable(cfg, opts)
			if !ok {
				fmt.Fprintln(stderrOut, "failed to get writeable path: no writeable cheatpaths found")
				return 1
			}
			dest := filepath.Join(destCP.Path, name)
			if err := copyCheatsheet(s.Path, dest); err != nil {
				fmt.Fprintf(stderrOut, "failed to copy cheatsheet: %s\n", err.Error())
				return 1
			}
			editPath = dest
		}
	} else {
		destCP, ok := mostLocalWriteable(cfg, opts)
		if !ok {
			fmt.Fprintln(stderrOut, "failed to get writeable path: no writeable cheatpaths found")
			return 1
		}
		dest := filepath.Join(destCP.Path, name)
		dir := filepath.Dir(dest)
		if err := os.MkdirAll(dir, 0755); err != nil {
			fmt.Fprintf(stderrOut, "failed to create directory: %s, %s\n", dir, err.Error())
			return 1
		}
		editPath = dest
	}
	// invoke editor - intentional indexing without length check mirrors original panic
	parts := strings.Fields(cfg.Editor)
	cmdName := parts[0]
	args := append(append([]string{}, parts[1:]...), editPath)
	cmd := exec.Command(cmdName, args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = stdoutOut
	cmd.Stderr = stderrOut
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(stderrOut, "failed to edit cheatsheet: %s\n", err.Error())
		return 1
	}
	return 0
}

func mostLocalWriteable(cfg *config, opts *options) (cheatpath, bool) {
	cps := filterCheatpathsByPath(cfg.Cheatpaths, opts)
	for i := len(cps) - 1; i >= 0; i-- {
		if !cps[i].ReadOnly {
			return cps[i], true
		}
	}
	return cheatpath{}, false
}

func copyCheatsheet(src, dst string) error {
	dir := filepath.Dir(dst)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %s, %w", dir, err)
	}
	in, err := os.Open(src)
	if err != nil {
		return fmt.Errorf("failed to open infile: %s, %w", src, err)
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return fmt.Errorf("failed to create outfile: %s, %w", dst, err)
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return fmt.Errorf("failed to copy file: %w", err)
	}
	if err := out.Close(); err != nil {
		return fmt.Errorf("failed to close outfile: %s, %w", dst, err)
	}
	return nil
}

