// handleMissingConfig returns exit code (does not proceed to command)
func handleMissingConfig(candidates []string) int {
	// first prompt
	fmt.Fprint(stdoutOut, "A config file was not found. Would you like to create one now? [Y/n]: ")
	answer, err := promptYesNo()
	if err != nil {
		fmt.Fprintf(stderrOut, "failed to create config: failed to prompt: %s\n", err.Error())
		return 1
	}
	if !answer {
		return 0
	}
	// installer
	candidate := ""
	if len(candidates) > 0 {
		candidate = candidates[0]
	}
	if err := runInstaller(candidate); err != nil {
		fmt.Fprintf(stderrOut, "failed to run installer: %s\n", err.Error())
		return 1
	}
	return 0
