func cmdEdit(cfg *config, opts *options) int {
	name := opts.Edit
	if err := validateCheatsheetName(name); err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	sheets, err := loadSheets(cfg)
	if err != nil {
		fmt.Fprintln(stderrOut, err.Error())
		return 1
	}
	filtered := filterByPathTag(sheets, opts, cfg)
	cands := filterExactTitle(filtered, name)
	var editPath string
	if s, ok := pickMostLocal(cands); ok {
		if !s.Cheatpath.ReadOnly {
			editPath = s.Path
		} else {
			// copy to most local writeable (path-filtered cheatpaths)
			destCP, ok := mostLocalWriteable(cfg, opts)
			if !ok {
				fmt.Fprintln(stderrOut, "failed to get writeable path: no writeable cheatpaths found")
				return 1
			}
			dest := filepath.Join(destCP.Path, name)
			if err := copyCheatsheet(s.Path, dest); err != nil {
				fmt.Fprintf(stderrOut, "failed to copy cheatsheet: %s\n", err.Error())
				return 1
			}
			editPath = dest
		}
	} else {
		destCP, ok := mostLocalWriteable(cfg, opts)
		if !ok {
			fmt.Fprintln(stderrOut, "failed to get writeable path: no writeable cheatpaths found")
			return 1
		}
		dest := filepath.Join(destCP.Path, name)
		dir := filepath.Dir(dest)
		if err := os.MkdirAll(dir, 0755); err != nil {
			fmt.Fprintf(stderrOut, "failed to create directory: %s, %s\n", dir, err.Error())
			return 1
		}
		editPath = dest
	}
	// invoke editor - intentional indexing without length check mirrors original panic
	parts := strings.Fields(cfg.Editor)
	cmdName := parts[0]
	args := append(append([]string{}, parts[1:]...), editPath)
	cmd := exec.Command(cmdName, args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = stdoutOut
	cmd.Stderr = stderrOut
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(stderrOut, "failed to edit cheatsheet: %s\n", err.Error())
		return 1
	}
	return 0
}

func mostLocalWriteable(cfg *config, opts *options) (cheatpath, bool) {
	cps := filterCheatpathsByPath(cfg.Cheatpaths, opts)
	for i := len(cps) - 1; i >= 0; i-- {
		if !cps[i].ReadOnly {
			return cps[i], true
		}
	}
	return cheatpath{}, false
}

func copyCheatsheet(src, dst string) error {
	dir := filepath.Dir(dst)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %s, %w", dir, err)
	}
	in, err := os.Open(src)
	if err != nil {
		return fmt.Errorf("failed to open infile: %s, %w", src, err)
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return fmt.Errorf("failed to create outfile: %s, %w", dst, err)
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return fmt.Errorf("failed to copy file: %w", err)
	}
	if err := out.Close(); err != nil {
		return fmt.Errorf("failed to close outfile: %s, %w", dst, err)
	}
	return nil
}

