import pathlib, os, shutil, subprocess, stat
def snapshot(home):
    items=[]
    for root, dirs, files in os.walk(home):
        dirs.sort(); files.sort()
        for d in dirs:
            p=os.path.join(root,d); rel=os.path.relpath(p,home); items.append((rel+"/","dir"))
        for f in files:
            p=os.path.join(root,f); rel=os.path.relpath(p,home)
            try: data=open(p,"rb").read()
            except Exception as e: data=str(e).encode()
            # skip git internals content variability? keep names only for .git
            if "/.git/" in p or p.endswith("/.git"):
                data=b"<git>"
            items.append((rel, data))
    return items

def run_scenario(name, steps):
    results=[]
    for binpath, home in [(ORIG,"/tmp/home_orig"),(OURS,"/tmp/home_ours")]:
        setup_home(home)
        outlog=[]
        for step in steps:
            kind=step[0]
            if kind=="write":
                _, rel, content = step
                fp=pathlib.Path(home)/rel; fp.parent.mkdir(parents=True, exist_ok=True)
                if isinstance(content, bytes): fp.write_bytes(content)
                else: fp.write_text(content)
            elif kind=="mkdir":
                (pathlib.Path(home)/step[1]).mkdir(parents=True, exist_ok=True)
            elif kind=="remove":
                fp=pathlib.Path(home)/step[1]
                if fp.is_dir(): shutil.rmtree(fp)
                elif fp.exists(): fp.unlink()
            elif kind=="chmod":
                os.chmod(pathlib.Path(home)/step[1], step[2])
            elif kind=="run":
                args=step[1]; env=step[2] if len(step)>2 else None; inp=step[3] if len(step)>3 else None; cwdrel=step[4] if len(step)>4 else None
                cwd = str(pathlib.Path(home)/cwdrel) if cwdrel else None
                code,out,err=run(binpath,args,home,env,inp,cwd)
                outlog.append((args,code,out.replace(home.encode(),b"/tmp/HOME"),err.replace(home.encode(),b"/tmp/HOME")))
            elif kind=="shell":
                # run shell command with HOME_BIN placeholders: $H = home
                cmd=step[1].replace("$H",home)
                r=subprocess.run(cmd, shell=True, capture_output=True)
                outlog.append(("shell:"+step[1], r.returncode, r.stdout.replace(home.encode(),b"/tmp/HOME"), r.stderr.replace(home.encode(),b"/tmp/HOME")))
        results.append((outlog, snapshot(home)))
    if results[0]!=results[1]:
        print(f"=== DIFF scenario {name}")
        o1,o2=results
        # print differences in logs
        for i,(a,b) in enumerate(zip(o1[0],o2[0])):
            if a!=b:
                print(f" step log {i}: orig={a}\n ours={b}")
        if o1[1]!=o2[1]:
            print(" filesystem diff:")
            s1=dict(o1[1]); s2=dict(o2[1])
            for k in sorted(set(s1)|set(s2)):
                if s1.get(k)!=s2.get(k):
                    print("  ",k, repr(s1.get(k))[:500], " vs ", repr(s2.get(k))[:500])
        return False
    else:
        print(f"OK scenario {name}")
        return True
