import pathlib
p=pathlib.Path("color.go"); s=p.read_text()
s=s.replace("langPlain\n\tlangGeneric // python-like names white", "langPlain\n\tlangGeneric // python-like names white\n\tlangTS")
s=s.replace('''	case "typescript", "ts":
		return langJS''','''	case "typescript", "ts":
		return langTS''')
# tokenize local isTS
s=s.replace('''func tokenize(text string, lang langKind) []token {
	if lang == langPlain {''','''func tokenize(text string, lang langKind) []token {
	isTS := lang == langTS
	if isTS {
		lang = langJS
	}
	if lang == langPlain {''')
# operator special for JS => before other operator handling: insert inside operator branch after Bash block start? Easiest insert before "// In Go" comment
s=s.replace('''			// In Go, = and punctuation are Text, not operator pink except some ops.''','''			if lang == langJS && !isTS && c == '=' && i+1 < n && text[i+1] == '>' {
				push(tokPunct, "=>")
				i += 2
				nextIsFuncName = false
				continue
			}
			// In Go, = and punctuation are Text, not operator pink except some ops.''')
p.write_text(s)
PY
gofmt -w color.go && go build -o /tmp/our_executable . && python3 - << 'PY'
