def fn(home): pathlib.Path(f"{home}/sheets/personal/jsarr").write_text("---\nsyntax: javascript\ntags: [ array, map ]\n---\n// To map over an array:\nconst squares = [1, 2, 3, 4].map(x => x * x);\n")
compare_custom(["-c","jsarr"], fn)
def fn2(home): pathlib.Path(f"{home}/sheets/personal/tsarr").write_text("---\nsyntax: typescript\n---\nconst f = (x: number) => x * 2;\n")
compare_custom(["-c","tsarr"], fn2)
PY"}

